def longest_equal_run(data):
    if not data:
        return 0
    current = best = 1
    for i in range(1, len(data)):
        if data[i] == data[i - 1]:
            current += 1
        else:
            current = 1
        if current > best:
            best = current
    return best

data = [2, 2, 5, 5, 5, 1, 1, 4]
print(longest_equal_run(data))
```

