def longest_run(data):
    if not data:
        return (-1, 0)
    start = best_start = 0
    current = best = 1
    for i in range(1, len(data)):
        if data[i] > data[i - 1]:
            current += 1
        else:
            start = i
            current = 1
        if current > best:
            best = current
            best_start = start
    return (best_start, best)

data = [4, 6, 8, 2, 5, 7, 1, 3]
print(longest_run(data))
```
